import type { BusinessStepDetail, ExecutionFacts, ReportHistoryPoint, TestType } from '../analytics/report.types';
import { formatTestType } from '../analytics/test-layer.classifier';

export interface BusinessDashboardOptions {
  history?: ReportHistoryPoint[];
  reportUrl?: string;
}

interface ChartItem { label: string; value: number }

/**
 * Author: Raushan Raj
 * Business Use: Renders an executive-first automation dashboard with static chart fallbacks and optional interactive filtering.
 * How to use: Generated by BusinessReporter or `npm run report:dashboard`; use `npm run report:serve` for the full interactive experience.
 * Benefit: Business users always see trustworthy KPIs/graphs, while QA can drill into test.step details and evidence without opening the technical Playwright report first.
 */
export function renderBusinessHtml(payload: ExecutionFacts, options: BusinessDashboardOptions = {}): string {
  const history = options.history ?? [];
  const aiUsage = payload.aiUsage ?? { calls: 0, healingCalls: 0, reportingCalls: 0, successfulCalls: 0, noResultCalls: 0, errorCalls: 0, budgetBlockedCalls: 0, averageLatencyMs: 0, providers: [], records: [] };
  const healedTestIds = new Set(payload.healing.records.map(record => record.testId).filter(Boolean));
  const projectOptions = unique(payload.results.map(result => result.project));
  const tagOptions = unique(payload.results.flatMap(result => result.tags));
  const categoryOptions = unique(payload.results.map(result => result.failureCategory).filter(Boolean) as string[]);
  const typeOptions = unique(payload.results.map(result => result.testType ?? 'OTHER')) as TestType[];
  const statusData: ChartItem[] = [
    { label: 'Passed', value: payload.passed },
    { label: 'Failed', value: payload.failed },
    { label: 'Skipped', value: payload.skipped }
  ];
  const layerData: ChartItem[] = [
    { label: 'UI', value: payload.layerCounts.UI },
    { label: 'API', value: payload.layerCounts.API },
    { label: 'Database', value: payload.layerCounts.DATABASE },
    { label: 'Other', value: payload.layerCounts.OTHER }
  ];
  const failureData: ChartItem[] = Object.entries(payload.failureCategoryCounts).map(([label, value]) => ({ label, value }));
  const rows = payload.results.map(result => {
    const healingForTest = payload.healing.records.filter(record => record.testId === result.testId);
    const displayStatus = result.flaky ? 'PASSED AFTER RETRY' : result.status === 'passed' && healingForTest.length ? 'PASSED WITH HEALING' : result.status.toUpperCase();
    const statusClass = result.status === 'failed' ? 'danger' : result.status === 'skipped' ? 'muted-badge' : result.flaky || healingForTest.length ? 'warn' : 'success';
    const type = result.testType ?? 'OTHER';
    const layers = result.layers ?? [];
    const tags = result.tags.length ? result.tags : ['—'];
    const stepDetails = result.stepDetails?.length ? renderStepTree(result.stepDetails) : result.steps.length
      ? `<ol class="simple-steps">${result.steps.map(step => `<li>${escapeHtml(step)}</li>`).join('')}</ol>`
      : '<p class="subtle">No business steps captured. Add test.step() to expose the business journey.</p>';
    const attachments = result.attachments ?? [];
    const evidence = attachments.length
      ? `<ul class="evidence-list">${attachments.map(item => item.reportPath
        ? `<li><a href="./${attr(item.reportPath)}" target="_blank" rel="noopener">${escapeHtml(item.name)}</a><span>${escapeHtml(item.contentType)}</span></li>`
        : `<li>${escapeHtml(item.name)}<span>${escapeHtml(item.contentType)}</span></li>`).join('')}</ul>`
      : '<p class="subtle">No shareable attachment copied for this scenario.</p>';
    return `<tr class="test-row" data-title="${attr(result.title.toLowerCase())}" data-file="${attr(shortFile(result.sourceFile).toLowerCase())}" data-status="${attr(result.status)}" data-project="${attr(result.project.toLowerCase())}" data-tags="${attr(result.tags.map(tag => tag.toLowerCase()).join('|'))}" data-type="${attr(type.toLowerCase())}" data-layers="${attr(layers.join('|').toLowerCase())}" data-category="${attr((result.failureCategory ?? '').toLowerCase())}" data-flaky="${result.flaky}" data-healed="${healedTestIds.has(result.testId)}" data-duration="${result.totalDurationMs}" data-retries="${result.retriesUsed}">
      <td><div class="scenario-title">${escapeHtml(result.title)}</div><div class="subtle">${escapeHtml(shortFile(result.sourceFile))}</div>
        <details class="scenario-details"><summary>View execution details</summary><div class="detail-grid"><div><h4>Business test steps</h4>${stepDetails}</div><div><h4>Execution evidence</h4><p><b>Layers:</b> ${layers.length ? layers.map(escapeHtml).join(' + ') : 'Other'}</p><p><b>Retries:</b> ${result.retriesUsed}</p><p><b>Flaky:</b> ${result.flaky ? 'Yes' : 'No'}</p><p><b>Self-healed:</b> ${healingForTest.length ? `Yes (${healingForTest.length})` : 'No'}</p>${result.error ? `<div class="error-box"><b>Failure:</b> ${escapeHtml(result.error)}</div>` : ''}<h4 class="evidence-heading">Attachments</h4>${evidence}</div></div></details>
      </td>
      <td><span class="badge ${statusClass}">${escapeHtml(displayStatus)}</span></td>
      <td><span class="type-pill">${escapeHtml(formatTestType(type))}</span></td>
      <td>${escapeHtml(result.project)}</td>
      <td>${tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</td>
      <td>${formatDuration(result.totalDurationMs)}</td><td>${result.retriesUsed}</td><td>${escapeHtml(result.failureCategory ?? '—')}</td>
    </tr>`;
  }).join('');

  const clusterCards = payload.failureClusters.length
    ? payload.failureClusters.map(cluster => `<article class="insight-card"><div class="insight-top"><span class="badge danger">${escapeHtml(cluster.category)}</span><b>${cluster.affectedTests} affected</b></div><h3>${escapeHtml(cluster.evidence)}</h3><p>${cluster.testTitles.map(escapeHtml).join('<br>')}</p></article>`).join('')
    : emptyState('No failure clusters', 'No final failures were observed in this business execution scope.');
  const impactCards = payload.businessImpacts.length
    ? payload.businessImpacts.map(impact => `<article class="insight-card"><div class="insight-top"><span class="badge ${impact.priority === 'HIGH' ? 'danger' : impact.priority === 'MEDIUM' ? 'warn' : 'success'}">${impact.priority}</span><b>${impact.affectedTests} affected</b></div><h3>${escapeHtml(impact.area)}</h3><p>${escapeHtml(impact.impact)}</p></article>`).join('')
    : emptyState('No mapped business impact', 'No configured business-impact rule matched a final failed scenario.');
  const healingRows = payload.healing.records.map(record => `<tr><td>${escapeHtml(record.businessName)}</td><td>${escapeHtml(record.decision.source.toUpperCase())}</td><td>${escapeHtml(record.decision.aiProvider ?? '—')}</td><td>${escapeHtml(record.decision.aiModel ?? '—')}</td><td>${Math.round(record.decision.confidence * 100)}%</td><td>${escapeHtml(record.decision.reason)}</td></tr>`).join('');
  const aiRows = aiUsage.records.map(record => `<tr><td>${escapeHtml(record.purpose)}</td><td>${escapeHtml(record.status)}</td><td>${escapeHtml(record.provider ?? '—')}</td><td>${escapeHtml(record.model ?? '—')}</td><td>${record.latencyMs === undefined ? '—' : `${record.latencyMs} ms`}</td><td>${escapeHtml(record.testId ?? 'run-level')}</td></tr>`).join('');
  const flakyRows = payload.flakiness.tests.map(test => `<tr><td>${escapeHtml(test.title)}</td><td>${escapeHtml(test.project)}</td><td>${test.attempts.map(attempt => `#${attempt.retry}: ${escapeHtml(attempt.status)}`).join('<br>')}</td></tr>`).join('');
  const excluded = payload.scope?.excludedInternalTests ?? 0;
  const dataJson = safeJson({ history, reportUrl: options.reportUrl ?? process.env.REPORT_PUBLIC_URL ?? '' });

  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enterprise Automation Dashboard</title>
<style>${styles()}</style></head><body><main class="shell">
<section class="hero"><div class="hero-top"><div><h1>Enterprise Automation Dashboard</h1><p>Release quality, risk, execution coverage and test evidence in one business-readable view.</p></div><span class="gate ${payload.qualityGate.status === 'PASSED' ? 'pass' : 'attention'}">${payload.qualityGate.status === 'PASSED' ? 'READY' : 'ATTENTION REQUIRED'}</span></div><div class="meta"><span>Run ${escapeHtml(payload.runId)}</span><span>Environment ${escapeHtml(payload.environment)}</span><span>Application ${escapeHtml(payload.application)}</span><span>Generated ${escapeHtml(formatDate(payload.generatedAt))}</span><span>Threshold ${payload.qualityGate.passThreshold}%</span></div><div class="scope-note">Business scope: ${payload.total} scenario(s) included · ${excluded} framework/internal check(s) excluded from business KPIs.</div></section>
<section class="kpis">${kpi('Business scenarios', payload.total, `${excluded} internal check(s) excluded`)}${kpi('Pass rate', `${payload.passRate}%`, `${payload.passed}/${payload.total} passed`)}${kpi('Failed', payload.failed, payload.failed ? 'Needs review' : 'No final failures')}${kpi('Flaky', payload.flakiness.flakyTests, `${payload.flakiness.totalRetryAttempts} retry attempt(s)`)}${kpi('Self-healed', payload.healing.count, `${payload.healing.ai} AI recovery event(s)`)}${kpi('AI calls', aiUsage.calls, `${aiUsage.successfulCalls} successful · ${aiUsage.averageLatencyMs} ms avg`)}${kpi('Duration', formatDuration(payload.durationMs), 'Business scenario duration')}</section>
<section class="grid">
<div class="panel span4 print-chart-panel"><div class="panel-head"><div><h2>Execution status</h2><div class="panel-sub">Current visible scenario composition</div></div></div><div class="donut-wrap"><div id="statusDonut" class="status-donut">${renderStatusDonutSvg(statusData, payload.passRate)}</div><div id="statusLegend" class="legend">${renderLegend(statusData)}</div></div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Coverage by layer</h2><div class="panel-sub">Mixed tests contribute to every layer they validate</div></div></div><div id="layerBars" class="bars">${renderBars(layerData)}</div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Failure categories</h2><div class="panel-sub">Final failed business scenarios only</div></div></div><div id="failureBars" class="bars">${renderBars(failureData)}</div></div>
<div class="panel span8"><div class="panel-head"><div><h2>Quality trend</h2><div class="panel-sub">Release-level pass rate; filters do not rewrite history</div></div></div>${renderTrendSvg(history)}</div>
<div class="panel span4"><div class="panel-head"><div><h2>Release decision</h2><div class="panel-sub">Deterministic gate, not an AI opinion</div></div></div><div class="insight-grid">${payload.qualityGate.reasons.map(reason => `<article class="insight-card"><span class="badge ${payload.qualityGate.status === 'PASSED' ? 'success' : 'danger'}">${payload.qualityGate.status === 'PASSED' ? 'READY' : 'ACTION'}</span><p>${escapeHtml(reason)}</p></article>`).join('')}</div><div class="trust section-space"><b>Trust model:</b> counts, pass rate, retries, failure clusters, layer classification and healing totals are framework facts. AI may explain evidence but cannot replace these values.</div></div>
</section>
<section class="panel section-space"><div class="panel-head"><div><h2>Test Explorer</h2><div class="panel-sub">Filter the release view, then expand any scenario to inspect test.step() details.</div></div><div class="actions"><button class="button secondary" id="expandBtn" type="button">Expand steps</button><button class="button secondary" id="collapseBtn" type="button">Collapse steps</button><button class="button secondary" id="printBtn" type="button">Print / PDF</button><button class="button" id="exportBtn" type="button">Export filtered CSV</button><a class="button secondary link-button" href="./business-tests.csv" download>Download all CSV</a></div></div>
<div id="dashboardJsStatus" class="runtime-state">Static dashboard ready · interactive controls loading…</div>
<div class="filters"><input id="searchFilter" placeholder="Search scenario, file or tag…"><select id="statusFilter"><option value="">All statuses</option><option value="passed">Passed</option><option value="failed">Failed</option><option value="skipped">Skipped</option></select><select id="layerFilter"><option value="">All layers</option><option value="ui">UI involved</option><option value="api">API involved</option><option value="database">Database involved</option></select><select id="typeFilter"><option value="">All test types</option>${typeOptions.map(type => `<option value="${type.toLowerCase()}">${escapeHtml(formatTestType(type))}</option>`).join('')}</select><select id="projectFilter"><option value="">All browsers/projects</option>${projectOptions.map(value => `<option value="${attr(value.toLowerCase())}">${escapeHtml(value)}</option>`).join('')}</select><select id="tagFilter"><option value="">All tags</option>${tagOptions.map(value => `<option value="${attr(value.toLowerCase())}">${escapeHtml(value)}</option>`).join('')}</select><select id="categoryFilter"><option value="">All failure categories</option>${categoryOptions.map(value => `<option value="${attr(value.toLowerCase())}">${escapeHtml(value)}</option>`).join('')}</select><select id="specialFilter"><option value="">All stability</option><option value="flaky">Flaky/retry recovered</option><option value="healed">Self-healed</option></select><select id="sortFilter"><option value="default">Default order</option><option value="status">Status</option><option value="duration-desc">Longest duration</option><option value="retries-desc">Most retries</option><option value="name">Scenario name</option></select><button class="button secondary" id="resetBtn" type="button">Reset</button></div>
<div class="toolbar-line"><div id="showing" class="showing">Showing ${payload.total} of ${payload.total} business scenarios</div><div class="filtered-kpis"><span class="mini-kpi" id="filteredPass">Pass ${payload.passed}</span><span class="mini-kpi" id="filteredFail">Fail ${payload.failed}</span><span class="mini-kpi" id="filteredSkip">Skip ${payload.skipped}</span></div></div>
<div class="table-wrap"><table id="testTable"><thead><tr><th>Scenario &amp; details</th><th>Status</th><th>Test type</th><th>Browser / Project</th><th>Tags</th><th>Duration</th><th>Retries</th><th>Failure category</th></tr></thead><tbody id="testTableBody">${rows}</tbody></table></div></section>
<section class="grid section-space"><div class="panel span6"><div class="panel-head"><div><h2>Business impact</h2><div class="panel-sub">Organization-approved impact statements for failed journeys</div></div></div><div class="insight-grid">${impactCards}</div></div><div class="panel span6"><div class="panel-head"><div><h2>Failure clusters</h2><div class="panel-sub">Repeated failures collapsed into common causes</div></div></div><div class="insight-grid">${clusterCards}</div></div></section>
<section class="panel section-space"><div class="panel-head"><div><h2>Self-healing audit</h2><div class="panel-sub">Every locator recovery remains visible and auditable; assertions are never auto-healed.</div></div><span class="badge success">${payload.healing.count} event(s)</span></div>${healingRows ? `<div class="table-wrap"><table><thead><tr><th>Business element</th><th>Source</th><th>Provider</th><th>Model</th><th>Confidence</th><th>Reason</th></tr></thead><tbody>${healingRows}</tbody></table></div>` : emptyState('No healing used', 'Primary locators remained stable in this run.')}</section>
<section class="panel section-space"><div class="panel-head"><div><h2>AI runtime audit</h2><div class="panel-sub">Operational proof of the provider/model actually called. Prompts, keys and raw model output are intentionally excluded.</div></div><span class="badge success">${aiUsage.calls} call(s)</span></div>${aiRows ? `<div class="table-wrap"><table><thead><tr><th>Purpose</th><th>Status</th><th>Provider</th><th>Model</th><th>Latency</th><th>Test</th></tr></thead><tbody>${aiRows}</tbody></table></div>` : emptyState('No AI calls used', 'This execution completed without invoking an AI provider.')}</section>
<section class="panel section-space"><div class="panel-head"><div><h2>Flaky / retry-recovered scenarios</h2><div class="panel-sub">Tests that changed outcome after retry need engineering review even when final result passed.</div></div></div>${flakyRows ? `<div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Project</th><th>Attempts</th></tr></thead><tbody>${flakyRows}</tbody></table></div>` : emptyState('No flaky tests detected', 'No scenario changed outcome after retry.')}</section>
<div class="footer">TestigentAI · Intelligent Quality Engineering Platform · Author: Raushan Raj · Use <b>npm run report:serve</b> for the fully interactive dashboard. Native test-step details remain expandable without JavaScript.</div></main>
<script id="dashboardData" type="application/json">${dataJson}</script><script src="./assets/dashboard.js" defer></script></body></html>`;
}

function renderStepTree(steps: BusinessStepDetail[]): string {
  return `<ol class="step-tree">${steps.map(step => `<li class="step ${step.status}"><div class="step-line"><span class="step-status">${step.status === 'passed' ? '✓' : step.status === 'failed' ? '✕' : '–'}</span><span class="step-title">${escapeHtml(step.title)}</span><span class="step-duration">${formatDuration(step.durationMs)}</span></div>${step.location?.file ? `<div class="step-meta">${escapeHtml(shortFile(step.location.file))}${step.location.line ? `:${step.location.line}` : ''}</div>` : ''}${step.error ? `<div class="error-box">${escapeHtml(step.error)}</div>` : ''}${step.params ? `<details class="params"><summary>Step parameters</summary><pre>${escapeHtml(JSON.stringify(step.params, null, 2))}</pre></details>` : ''}${step.children.length ? renderStepTree(step.children) : ''}</li>`).join('')}</ol>`;
}

function styles(): string { return `
:root{--navy:#0f172a;--blue:#2563eb;--green:#059669;--red:#dc2626;--amber:#d97706;--muted:#64748b;--line:#e2e8f0;--bg:#f8fafc;--shadow:0 8px 28px rgba(15,23,42,.07)}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:#0f172a}.shell{max-width:1540px;margin:auto;padding:28px}.hero{background:linear-gradient(120deg,#0f172a,#172554 58%,#1d4ed8);color:#fff;border-radius:22px;padding:28px;box-shadow:var(--shadow)}.hero-top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.hero h1{margin:0;font-size:30px}.hero p{margin:8px 0 0;color:#cbd5e1}.gate{padding:10px 14px;border-radius:999px;font-weight:800;font-size:13px}.gate.pass{background:#d1fae5;color:#065f46}.gate.attention{background:#fee2e2;color:#991b1b}.meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.meta span{font-size:12px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);padding:6px 9px;border-radius:8px}.scope-note{margin-top:12px;font-size:12px;color:#dbeafe}.kpis{display:grid;grid-template-columns:repeat(6,minmax(140px,1fr));gap:14px;margin:20px 0}.kpi,.panel{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.kpi{padding:16px}.kpi-label{color:var(--muted);font-size:12px;font-weight:700;text-transform:uppercase}.kpi-value{font-size:28px;font-weight:800;margin-top:5px}.kpi-note,.panel-sub,.subtle,.step-meta{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.panel{padding:18px}.panel h2{font-size:17px;margin:0}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.span4{grid-column:span 4}.span6{grid-column:span 6}.span8{grid-column:span 8}.donut-wrap{display:flex;align-items:center;justify-content:center;gap:24px;min-height:210px}.status-donut{width:170px;height:170px;display:grid;place-items:center;flex:0 0 170px}.status-donut-svg{width:170px;height:170px;overflow:visible}.status-donut-svg .donut-track{fill:none;stroke:#e2e8f0;stroke-width:16}.status-donut-svg .donut-segment{fill:none;stroke-width:16;stroke-linecap:butt;transform:rotate(-90deg);transform-origin:60px 60px}.status-donut-svg .donut-rate{font-size:18px;font-weight:800;fill:#0f172a;text-anchor:middle}.status-donut-svg .donut-label{font-size:8px;fill:#64748b;text-anchor:middle}.legend,.bars{display:grid;gap:10px}.legend-row{display:flex;gap:8px;align-items:center}.legend-dot{width:10px;height:10px;flex:0 0 10px}.bar-row{display:grid;grid-template-columns:115px 1fr 44px;gap:10px;align-items:center;font-size:13px}.bar-track{height:11px;background:#e2e8f0;border-radius:999px;overflow:hidden}.bar-fill{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#2563eb,#60a5fa)}.trend{width:100%;height:220px}.empty{padding:24px;text-align:center;color:var(--muted);border:1px dashed #cbd5e1;border-radius:12px}.section-space{margin-top:18px}.filters{position:sticky;top:8px;z-index:20;display:grid;grid-template-columns:2fr repeat(7,minmax(115px,1fr)) auto;gap:9px;padding:12px;background:rgba(255,255,255,.97);backdrop-filter:blur(10px);border:1px solid var(--line);border-radius:14px;margin:16px 0}.filters input,.filters select{width:100%;border:1px solid #cbd5e1;border-radius:9px;padding:9px 10px;background:#fff}.button{border:0;border-radius:9px;padding:9px 13px;font-weight:700;cursor:pointer;background:#0f172a;color:#fff;text-decoration:none;display:inline-block;font-size:13px}.button.secondary{background:#fff;color:#0f172a;border:1px solid #cbd5e1}.actions{display:flex;gap:8px;flex-wrap:wrap}.runtime-state{font-size:12px;padding:8px 10px;border-radius:8px;background:#e0f2fe;color:#075985}.runtime-state.ready{background:#d1fae5;color:#065f46}.runtime-state.error{background:#fee2e2;color:#991b1b}.toolbar-line{display:flex;justify-content:space-between;gap:10px;align-items:center}.filtered-kpis{display:flex;gap:8px;flex-wrap:wrap}.mini-kpi{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:6px 9px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:14px}table{width:100%;border-collapse:collapse;min-width:1050px}th{background:#f8fafc;text-align:left;font-size:11px;text-transform:uppercase;color:#64748b;padding:12px;border-bottom:1px solid var(--line)}td{padding:12px;border-bottom:1px solid #eef2f7;font-size:13px;vertical-align:top}.scenario-title{font-weight:750}.badge,.type-pill,.tag{display:inline-flex;border-radius:999px;font-weight:800;font-size:10px;padding:5px 8px}.badge.success{background:#d1fae5;color:#065f46}.badge.danger{background:#fee2e2;color:#991b1b}.badge.warn{background:#fef3c7;color:#92400e}.badge.muted-badge{background:#e2e8f0;color:#475569}.type-pill{background:#dbeafe;color:#1e40af}.tag{background:#f1f5f9;color:#475569;margin:1px}.scenario-details{margin-top:8px;border:1px solid #e2e8f0;border-radius:10px;padding:8px;background:#fbfdff}.scenario-details summary,.params summary{cursor:pointer;font-weight:700;color:#1d4ed8}.detail-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:20px;padding:12px 2px 2px}.step-tree{margin:8px 0 0;padding-left:20px}.step-tree .step{margin:8px 0}.step-line{display:flex;gap:8px;align-items:center}.step-status{font-weight:900}.step.passed>.step-line .step-status{color:var(--green)}.step.failed>.step-line .step-status{color:var(--red)}.step-title{font-weight:650}.step-duration{margin-left:auto;color:var(--muted);font-size:11px}.step-meta{margin:3px 0 0 24px}.params{margin:6px 0 0 24px}.params pre{white-space:pre-wrap;background:#f8fafc;border:1px solid #e2e8f0;padding:8px;border-radius:8px}.error-box{margin-top:8px;background:#fff1f2;border-left:4px solid #ef4444;padding:10px;border-radius:6px;white-space:pre-wrap}.evidence-list{padding-left:18px}.evidence-list li{margin:6px 0}.evidence-list span{display:block;color:var(--muted);font-size:11px}.evidence-heading{margin-top:16px}.insight-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.insight-card{border:1px solid var(--line);border-radius:14px;padding:14px}.insight-card h3{font-size:14px}.insight-card p{font-size:12px;color:var(--muted);line-height:1.5}.insight-top{display:flex;justify-content:space-between}.trust{font-size:12px;line-height:1.5;background:#eff6ff;border-left:4px solid #3b82f6;padding:12px;border-radius:8px}.footer{padding:24px 0 8px;color:#94a3b8;font-size:11px;text-align:center}@media(max-width:1200px){.filters{grid-template-columns:repeat(4,1fr)}}@media(max-width:1050px){.kpis{grid-template-columns:repeat(3,1fr)}.span4,.span6,.span8{grid-column:span 12}.hero-top{flex-direction:column}}@media(max-width:680px){.shell{padding:12px}.kpis{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}}@page{size:A4 landscape;margin:10mm}@media print{*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}body{background:#fff}.filters,.button,.runtime-state{display:none!important}.panel,.kpi,.hero{box-shadow:none}.shell{max-width:none;padding:0}.print-chart-panel{break-inside:avoid;page-break-inside:avoid}.status-donut,.status-donut-svg,.trend{display:block!important;visibility:visible!important}.status-donut-svg{width:160px;height:160px}.scenario-details{border:0;padding:0}.scenario-details>summary{display:none}.scenario-details>*{display:block!important}details:not([open])>*:not(summary){display:block!important}}
`; }

function kpi(label: string, value: string | number, note: string): string { return `<div class="kpi"><div class="kpi-label">${escapeHtml(label)}</div><div class="kpi-value">${escapeHtml(String(value))}</div><div class="kpi-note">${escapeHtml(note)}</div></div>`; }
function renderLegend(items: ChartItem[]): string { const colors: Record<string,string> = { Passed:'#059669',Failed:'#dc2626',Skipped:'#94a3b8' }; return items.map(item => `<div class="legend-row"><svg class="legend-dot" viewBox="0 0 10 10" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="${colors[item.label] ?? '#2563eb'}"/></svg><span>${escapeHtml(item.label)}</span><b>${item.value}</b></div>`).join(''); }
function renderBars(items: ChartItem[]): string { if (!items.length || items.every(item => item.value === 0)) return '<div class="empty">No data for this run.</div>'; const max = Math.max(1,...items.map(item=>item.value)); return items.map(item=>`<div class="bar-row"><span>${escapeHtml(item.label)}</span><span class="bar-track"><span class="bar-fill" style="width:${item.value/max*100}%"></span></span><b>${item.value}</b></div>`).join(''); }
function renderStatusDonutSvg(items: ChartItem[], passRate: number): string {
  const colors: Record<string,string> = { Passed:'#059669',Failed:'#dc2626',Skipped:'#94a3b8' };
  const radius = 50;
  const circumference = 2 * Math.PI * radius;
  const total = items.reduce((sum,item)=>sum+item.value,0);
  let cursor = 0;
  const segments = total
    ? items.map(item => {
        const length = (item.value / total) * circumference;
        const offset = -cursor;
        cursor += length;
        return `<circle class="donut-segment" data-status="${attr(item.label.toLowerCase())}" cx="60" cy="60" r="${radius}" stroke="${colors[item.label] ?? '#2563eb'}" stroke-dasharray="${length.toFixed(3)} ${(circumference-length).toFixed(3)}" stroke-dashoffset="${offset.toFixed(3)}"/>`;
      }).join('')
    : '';
  return `<svg class="status-donut-svg" viewBox="0 0 120 120" role="img" aria-label="Execution status: ${items.map(item=>`${item.label} ${item.value}`).join(', ')}"><circle class="donut-track" cx="60" cy="60" r="${radius}"/>${segments}<text id="donutPassRate" class="donut-rate" x="60" y="57">${escapeHtml(String(passRate))}%</text><text class="donut-label" x="60" y="72">pass rate</text></svg>`;
}
function renderTrendSvg(history: ReportHistoryPoint[]): string { if(history.length<2)return '<div id="trendEmpty" class="empty">Run more executions to build a quality trend.</div>'; const W=760,H=220,P=30; const xs=history.map((_,i)=>P+i*(W-2*P)/(history.length-1)); const ys=history.map(p=>H-P-(Math.max(0,Math.min(100,p.passRate))/100)*(H-2*P)); const points=xs.map((x,i)=>`${x},${ys[i]}`).join(' '); const circles=history.map((p,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="5" fill="#fff" stroke="#2563eb" stroke-width="3"><title>${escapeHtml(p.runId)}: ${p.passRate}%</title></circle>`).join(''); return `<svg id="trendChart" class="trend" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" stroke="#cbd5e1"/><line x1="${P}" y1="${P}" x2="${P}" y2="${H-P}" stroke="#cbd5e1"/><polyline fill="none" stroke="#2563eb" stroke-width="4" points="${points}"/>${circles}<text x="${P}" y="18" font-size="11" fill="#64748b">100%</text><text x="${P}" y="${H-7}" font-size="11" fill="#64748b">0%</text></svg>`; }
function emptyState(title:string,text:string):string{return `<div class="empty"><b>${escapeHtml(title)}</b><br>${escapeHtml(text)}</div>`;}
function formatDuration(ms:number):string{return ms>=1000?`${(ms/1000).toFixed(ms>=10000?0:1)} s`:`${Math.round(ms)} ms`;}
function formatDate(value:string):string{const d=new Date(value); return Number.isNaN(d.getTime())?value:d.toLocaleString('en-GB');}
function shortFile(value?:string):string{return value?value.replace(process.cwd()+'/',''):'—';}
function unique<T>(values:T[]):T[]{return [...new Set(values)].sort() as T[];}
function escapeHtml(value:string):string{return value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]??c));}
function attr(value:string):string{return escapeHtml(value);}
function safeJson(value:unknown):string{return JSON.stringify(value).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');}
